CREATE PROCEDURE U3CountMarked(IN p_course VARCHAR, OUT p_marked BIGINT)
LANGUAGE plpgsql AS $$
BEGIN
  IF p_course IS NULL THEN
    RAISE EXCEPTION 'Course code is required';
  END IF;
  SELECT COUNT(mark) INTO p_marked FROM U3Enrolment
  WHERE course_code = p_course;
END;
$$;
CALL U3CountMarked('DB101', NULL);

