sqlserver.code:
GO
CREATE PROCEDURE U3CountMarked
  @course VARCHAR(10), @marked INTEGER OUTPUT
AS
BEGIN
  SET NOCOUNT ON;
  IF @course IS NULL
    THROW 50001, 'Course code is required', 1;
  SELECT @marked = COUNT(mark) FROM U3Enrolment
  WHERE course_code = @course;
END;
GO
DECLARE @n INTEGER;
EXEC U3CountMarked @course = 'DB101', @marked = @n OUTPUT;
SELECT @n AS recorded_marks;
